'use strict';
let selectedMapItem=null;
function mapItem(ref){if(!ref)return null;if(ref.kind==='member'){const m=state.members.find(m=>m.id===ref.id),box=slotBy(m?.slot);return box?{ref,box,locked:!!m.locked,label:m.name}:null}const list=ref.kind==='slot'?state.slots:ref.kind==='terrain'?state.blocks:state.structures,box=list.find(o=>o.id===ref.id);return box?{ref,box,locked:false,label:ref.kind==='slot'?'+ City':ref.kind==='terrain'?'Terrain':box.kind==='hq'?'Alliance HQ':box.kind==='node'?'Resource node':'Banner'}:null}
function hitDraggable(p){const inside=b=>visible(b)&&p.x>=b.x&&p.x<b.x+b.w&&p.y>=b.y&&p.y<b.y+b.h;const slot=state.slots.find(inside);if(slot){const m=memberAt(slot.id);return mapItem({kind:m?'member':'slot',id:m?m.id:slot.id})}const b=state.blocks.find(inside);if(b)return mapItem({kind:'terrain',id:b.id});const o=state.structures.find(inside);return o?mapItem({kind:'object',id:o.id}):null}
function canDragItem(ref,x,y){try{Hive.moveMapItem(state,ref,x,y);return true}catch{return false}}
function applyDragItem(ref,x,y){try{const item=mapItem(ref);if(item.box.x===x&&item.box.y===y)return;const next=Hive.moveMapItem(state,ref,x,y);commit(()=>state=next);selectedMapItem=ref;setTool('select');renderMap();toast('Position updated. Undo is available.')}catch(e){toast(e.message)}}
function removeSelectedMapItem(){const item=mapItem(selectedMapItem);if(!item||readonly)return;try{const ref=item.ref,target=ref.kind==='member'?{memberId:ref.id}:ref.kind==='slot'?{slotId:ref.id}:ref.kind==='terrain'?{terrainId:ref.id}:{objectId:ref.id};const next=Hive.removeMapObject(state,target);commit(()=>state=next);selectedMapItem=null;renderMap();toast(ref.kind==='member'?'City removed. Player kept in the queue. Undo is available.':'Item removed. Undo is available.')}catch(e){toast(e.message)}}
const directBaseTap=mapTap;mapTap=function(e,target){if(target.closest('[data-map-action]'))return;if(readonly||tool!=='select'){directBaseTap(e,target);if(!readonly&&['slot','block','flag','hq','assign'].includes(tool)){setTool('select');renderMap()}return}const r=viewport.getBoundingClientRect(),hit=hitDraggable(screenWorld(e.clientX-r.left,e.clientY-r.top));if(hit){selectedMapItem=hit.ref;selectedSlot=hit.ref.kind==='slot'?hit.ref.id:hit.ref.kind==='member'?state.members.find(m=>m.id===hit.ref.id).slot:null;renderMap();return}selectedMapItem=null;selectedSlot=null;selectedMember=null;renderMap();directBaseTap(e,target)};
const directBaseMap=renderMap;renderMap=function(){directBaseMap();let actions=$('#mapItemActions');if(!actions){actions=document.createElement('div');actions.id='mapItemActions';actions.className='map-item-actions';viewport.appendChild(actions)}const item=mapItem(selectedMapItem);if(item){const shape=item.ref.kind==='member'?$('#mapSvg').querySelector('[data-slot="'+state.members.find(m=>m.id===item.ref.id).slot+'"] polygon'):item.ref.kind==='slot'?$('#mapSvg').querySelector('[data-slot="'+item.ref.id+'"] polygon'):null;if(shape){shape.setAttribute('stroke','#263e31');shape.setAttribute('stroke-width','3')}}if(!item||readonly||mapDrag?.started){actions.hidden=true;return}actions.hidden=false;const c=point(item.box.x+item.box.w/2,item.box.y+item.box.h/2);actions.style.left=Math.max(108,Math.min(view.w-108,c.x))+'px';actions.style.top=Math.max(8,Math.min(view.h-(item.ref.kind==='slot'?265:105),c.y-66))+'px';actions.innerHTML=`<span>${esc(item.label)}${item.locked?' · Locked':''}</span><div><button data-map-action="details" aria-label="${item.ref.kind==='slot'?'Choose player':'Item details'}">${item.ref.kind==='slot'?'Choose player':'Details'}</button><button data-map-action="remove" aria-label="Remove ${esc(item.label)} from map" ${item.locked?'disabled':''}>−</button></div>`;actions.querySelector('[data-map-action="remove"]').onclick=removeSelectedMapItem;actions.querySelector('[data-map-action="details"]').onclick=()=>{if(item.ref.kind==='member')memberDetail(item.ref.id);else if(item.ref.kind==='slot')openSlot(item.ref.id);else objectModal(item.box,item.ref.kind==='terrain')};if(item.ref.kind==='slot'){const candidates=Hive.rankedSlotMembers(state,item.box.trap).filter(m=>!m.locked).slice(0,3);const list=document.createElement('div');list.className='quick-city-players';list.innerHTML=candidates.map(m=>`<button data-map-action="player" data-quick-player="${esc(m.id)}">${esc(m.name)}</button>`).join('');actions.appendChild(list);list.querySelectorAll('[data-quick-player]').forEach(b=>b.onclick=()=>{try{const next=Hive.assignSlotMember(state,item.ref.id,b.dataset.quickPlayer);commit(()=>state=next);selectedMapItem={kind:'member',id:b.dataset.quickPlayer};renderMap();toast('Player assigned. Undo is available.')}catch(e){toast(e.message)}})}};
// All editing tools are one-shot placement actions. Tap the active tool to cancel.
$$('[data-tool]').forEach(b=>{const prior=b.onclick;b.onclick=()=>{selectedMapItem=null;if(tool===b.dataset.tool){setTool('select');renderMap()}else prior()}});
// Inline controls replace the phone-only modal panels.
closeMapSheets();$('#toggleQueue').hidden=true;$('#toggleTools').hidden=true;$('#closeQueueSheet').hidden=true;$('#closeToolsSheet').hidden=true;
renderMap();
